-- >>> ÜRETİLEN

-- Birim (Birim)
CREATE TABLE "birim" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "birim_id" varchar(32) NOT NULL UNIQUE,
    "ad" varchar(255) NOT NULL,
    "turu1" varchar(8) NOT NULL DEFAULT '',
    "turu2" varchar(8) NOT NULL DEFAULT '',
    "turu3" varchar(8) NOT NULL DEFAULT '',
    "yargi_turu" smallint NULL CHECK ("yargi_turu" >= 0),
    "olusturulma" timestamp with time zone NOT NULL DEFAULT now(),
    "guncelleme" timestamp with time zone NOT NULL DEFAULT now()
);

-- YargiBirimi (Yargı Birimi)
CREATE TABLE "yargi_birimi" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "yargi_turu" smallint NOT NULL CHECK ("yargi_turu" >= 0),
    "kod" varchar(8) NOT NULL,
    "ad" varchar(120) NOT NULL,
    "olusturulma" timestamp with time zone NOT NULL DEFAULT now(),
    "guncelleme" timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT "uq_yargi_birimi" UNIQUE ("yargi_turu", "kod")
);

-- SenkronKapsami (Senkron Kapsamı)
CREATE TABLE "senkron_kapsami" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "yargi_turu" smallint NOT NULL CHECK ("yargi_turu" >= 0),
    "yargi_birimi_kod" varchar(8) NOT NULL DEFAULT '',
    "aktif" boolean NOT NULL DEFAULT true,
    "olusturulma" timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT "uq_senkron_kapsami" UNIQUE ("yargi_turu", "yargi_birimi_kod")
);

-- Taraf (Taraf)
CREATE TABLE "taraf" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "tur" varchar(8) NOT NULL,
    "ad" varchar(120) NOT NULL DEFAULT '',
    "soyad" varchar(120) NOT NULL DEFAULT '',
    "tckn" varchar(11) NULL UNIQUE,
    "unvan" varchar(400) NOT NULL DEFAULT '',
    "mersis_no" varchar(20) NULL UNIQUE,
    "vergi_no" varchar(15) NOT NULL DEFAULT '',
    "e_tebligat_adresi" varchar(255) NOT NULL DEFAULT '',
    "kep_adresi" varchar(255) NOT NULL DEFAULT '',
    "adres" text NOT NULL DEFAULT '',
    "iban" varchar(34) NOT NULL DEFAULT '',
    "olusturulma" timestamp with time zone NOT NULL DEFAULT now(),
    "guncelleme" timestamp with time zone NOT NULL DEFAULT now()
);

-- Vekil (Vekil)
CREATE TABLE "vekil" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "ad" varchar(120) NOT NULL,
    "soyad" varchar(120) NOT NULL DEFAULT '',
    "tckn" varchar(11) NULL UNIQUE,
    "baro_sicil" varchar(40) NOT NULL DEFAULT '',
    "adres" text NOT NULL DEFAULT '',
    "iban" varchar(34) NOT NULL DEFAULT '',
    "olusturulma" timestamp with time zone NOT NULL DEFAULT now(),
    "guncelleme" timestamp with time zone NOT NULL DEFAULT now()
);

-- Dosya (Dosya)
CREATE TABLE "dosya" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "dosya_id" varchar(255) NOT NULL DEFAULT '',
    "birim_id" bigint NOT NULL,
    "yargi_turu" smallint NOT NULL CHECK ("yargi_turu" >= 0),
    "yil" integer NOT NULL CHECK ("yil" >= 0),
    "sira_no" integer NOT NULL CHECK ("sira_no" >= 0),
    "dosya_no" varchar(255) NOT NULL,
    "durum_kod" integer NOT NULL DEFAULT 0,
    "durum" varchar(255) NOT NULL DEFAULT '',
    "tur_kod" integer NOT NULL DEFAULT 0,
    "tur" varchar(255) NOT NULL DEFAULT '',
    "acilis_tarihi" timestamp with time zone NULL,
    "is_dava_dosyasi_acilmis" boolean NOT NULL DEFAULT false,
    "islem_durumu" varchar(12) NOT NULL DEFAULT 'aktif',
    "islem_durumu_notu" text NOT NULL DEFAULT '',
    "islem_durumu_tarihi" timestamp with time zone NULL,
    "bekleme_bitis_tarihi" date NULL,
    "son_senkron" timestamp with time zone NOT NULL DEFAULT now(),
    "olusturulma" timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT "uq_dosya_kunye" UNIQUE ("birim_id", "yil", "sira_no", "tur_kod")
);

-- DosyaTaraf (Dosya Tarafı)
CREATE TABLE "dosya_taraf" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "dosya_id" bigint NOT NULL,
    "taraf_id" bigint NOT NULL,
    "rol" varchar(255) NOT NULL,
    "sira" integer NOT NULL CHECK ("sira" >= 0) DEFAULT 0,
    "kesinlesme_durumu" varchar(30) NOT NULL DEFAULT '',
    "kesinlesme_tarihi" date NULL,
    "tebligat_durumu" varchar(30) NOT NULL DEFAULT '',
    "tebligat_durum_tarihi" date NULL,
    "tebligat_sekli" varchar(150) NOT NULL DEFAULT '',
    "itiraz_edildi_mi" boolean NOT NULL DEFAULT false,
    "itiraz_tarihi" date NULL,
    "uyapta_gorulmedi" timestamp with time zone NULL,
    CONSTRAINT "uq_dosya_taraf_rol" UNIQUE ("dosya_id", "taraf_id", "rol")
);
CREATE TABLE "dosya_taraf_vekiller" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "dosyataraf_id" bigint NOT NULL,
    "vekil_id" bigint NOT NULL
);

-- IcraTakipDetay (İcra Takip Detayı)
CREATE TABLE "icra_takip_detay" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "dosya_id" bigint NOT NULL UNIQUE,
    "takibin_turu" varchar(8) NOT NULL DEFAULT '',
