    "takibin_sekli" varchar(8) NOT NULL DEFAULT '',
    "takibin_sekli_aciklama" varchar(255) NOT NULL DEFAULT '',
    "takibin_yolu" varchar(8) NOT NULL DEFAULT '',
    "takibin_yolu_aciklama" varchar(120) NOT NULL DEFAULT '',
    "alacak_kalemi_toplam" numeric(14, 2) NOT NULL DEFAULT 0,
    "alacak_kalemi_faiz" numeric(14, 2) NOT NULL DEFAULT 0,
    "takip_sonrasi_masraf" numeric(14, 2) NOT NULL DEFAULT 0,
    "vekalet_ucreti" numeric(14, 2) NOT NULL DEFAULT 0,
    "tahsil_harci" numeric(14, 2) NOT NULL DEFAULT 0,
    "yapilmis_tahsilat" numeric(14, 2) NOT NULL DEFAULT 0,
    "bsmv_ucreti" numeric(14, 2) NOT NULL DEFAULT 0,
