    "kkdf_ucreti" numeric(14, 2) NOT NULL DEFAULT 0,
    "ozel_iletisim_vergisi" numeric(14, 2) NOT NULL DEFAULT 0,
    "guncelleme" timestamp with time zone NOT NULL DEFAULT now()
);

-- HukukDavaDetay (Hukuk Dava Detayı)
CREATE TABLE "hukuk_dava_detay" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "dosya_id" bigint NOT NULL UNIQUE,
    "dava_acilis_turu" varchar(120) NOT NULL DEFAULT '',
    "dava_turleri" varchar(500) NOT NULL DEFAULT '',
    "ilgili_dosya_listesi" varchar(500) NOT NULL DEFAULT '',
