    "karar_no" varchar(40) NOT NULL DEFAULT '',
    "karar_tarihi" varchar(40) NOT NULL DEFAULT '',
    "karar_zamani" timestamp with time zone NULL,
    "guncelleme" timestamp with time zone NOT NULL DEFAULT now()
);

-- DosyaSafahat (Dosya Safahatı)
CREATE TABLE "dosya_safahat" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "dosya_id" bigint NOT NULL,
    "islem_yapan_birim" varchar(255) NOT NULL DEFAULT '',
    "safahat_tarihi" varchar(40) NOT NULL DEFAULT '',
    "safahat_zamani" timestamp with time zone NULL,
    "safahat_turu_kod" integer NULL,
    "safahat_turu_aciklama" varchar(255) NOT NULL DEFAULT '',
