);

-- DosyaTahsilatHarc (Dosya Tahsilat/Harç Kaydı)
CREATE TABLE "dosya_tahsilat_harc" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "dosya_id" bigint NOT NULL,
    "tur" varchar(10) NOT NULL,
