-- IcraDosyaHesabi (İcra Dosya Hesap Kalemi)
CREATE TABLE "icra_dosya_hesabi" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "dosya_id" bigint NOT NULL,
    "grup_id" smallint NOT NULL CHECK ("grup_id" >= 0),
    "metin_alan" varchar(120) NOT NULL,
    "deger_alan" numeric(14, 2) NULL,
    "guncelleme" timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT "uq_icra_dosya_hesap_kalemi" UNIQUE ("dosya_id", "metin_alan", "grup_id")
);

-- BorcluSorgu (Borçlu Malvarlığı Sorgusu)
CREATE TABLE "borclu_sorgu" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "dosya_id" bigint NOT NULL,
