    "has_error" boolean NOT NULL DEFAULT false,
    "has_data" boolean NOT NULL DEFAULT false,
    "sonuc" jsonb NULL,
    "olusturulma" timestamp with time zone NOT NULL DEFAULT now()
);

-- TebligatBarkod (Tebligat Barkod Sorgusu)
CREATE TABLE "tebligat_barkod" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "dosya_id" bigint NOT NULL,
    "birim_evrak_no" integer NOT NULL CHECK ("birim_evrak_no" >= 0),
    "borclu_id" bigint NULL,
    "evrak_aciklama" varchar(500) NOT NULL DEFAULT '',
    "evrak_tarihi" varchar(40) NOT NULL DEFAULT '',
    "evrak_gunu" date NULL,
    "barkod" varchar(32) NOT NULL DEFAULT '',
    "elektronik_tebligat" boolean NOT NULL DEFAULT false,
    "tebligat_turu" varchar(120) NOT NULL DEFAULT '',
    "ptt_durumu" varchar(255) NOT NULL DEFAULT '',
    "son_islem_tarihi" varchar(40) NOT NULL DEFAULT '',
    "son_islem_zamani" timestamp with time zone NULL,
    "ham_yanit" jsonb NULL,
