    "t212_tarandi_zamani" timestamp with time zone NULL,
    "sorgu_zamani" timestamp with time zone NOT NULL DEFAULT now(),
    "olusturulma" timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT "uq_dosya_tebligat_barkod" UNIQUE ("dosya_id", "birim_evrak_no")
);

-- Evrak (Evrak)
CREATE TABLE "evrak" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "dosya_id" bigint NOT NULL,
    "ust_evrak_id" bigint NULL,
    "birim_evrak_no" integer NOT NULL CHECK ("birim_evrak_no" >= 0),
    "evrak_turu" varchar(64) NOT NULL DEFAULT '',
