    "aciklama" varchar(500) NOT NULL DEFAULT '',
    "evrak_tarihi" timestamp with time zone NULL,
    "mime_turu" varchar(64) NOT NULL DEFAULT '',
    "boyut" integer NOT NULL CHECK ("boyut" >= 0) DEFAULT 0,
    "sha256" varchar(64) NOT NULL DEFAULT '',
    "dosya_yolu" varchar(500) NOT NULL DEFAULT '',
    "degisebilir" boolean NOT NULL DEFAULT false,
    "indirilme_zamani" timestamp with time zone NOT NULL DEFAULT now(),
    "son_erisim_zamani" timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT "uq_dosya_evrak" UNIQUE ("dosya_id", "birim_evrak_no")
);

-- KesinlesmeKurali (Kesinleşme Kuralı)
CREATE TABLE "kesinlesme_kurali" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "takibin_turu" varchar(8) NOT NULL DEFAULT '',
    "takibin_yolu" varchar(8) NOT NULL DEFAULT '',
    "takibin_sekli" varchar(8) NOT NULL DEFAULT '',
    "ad" varchar(160) NOT NULL DEFAULT '',
    "itiraz_suresi_gun" smallint NULL CHECK ("itiraz_suresi_gun" >= 0),
    "aktif" boolean NOT NULL DEFAULT true,
    "aciklama" text NOT NULL DEFAULT '',
    "guncelleme" timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT "uq_kesinlesme_kurali" UNIQUE ("takibin_turu", "takibin_yolu", "takibin_sekli")
);

-- ResmiTatil (Resmi Tatil)
CREATE TABLE "resmi_tatil" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "tarih" date NOT NULL UNIQUE,
    "aciklama" varchar(120) NOT NULL DEFAULT ''
);

-- PttHareket (PTT Hareketi)
CREATE TABLE "ptt_hareket" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "tebligat_id" bigint NOT NULL,
    "sira" smallint NOT NULL CHECK ("sira" >= 0),
    "zaman" timestamp with time zone NULL,
