    "tur" varchar(20) NOT NULL,
    "eski" varchar(255) NOT NULL DEFAULT '',
    "yeni" varchar(255) NOT NULL DEFAULT '',
    "olay_tarihi" date NULL,
    "kaynak" varchar(8) NOT NULL DEFAULT 'hesap',
    "aciklama" text NOT NULL DEFAULT '',
    "zaman" timestamp with time zone NOT NULL DEFAULT now()
);

-- TebligatTurEslesmesi (Tebligat Tür Eşleşmesi)
CREATE TABLE "tebligat_tur_eslesmesi" (
    "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "anahtar" text NOT NULL UNIQUE,
    "tur" varchar(120) NOT NULL,
